fn decode_effect_kind(op: Opcode, cursor: &mut &[u8]) -> Option<Box<EffectKind>> {
    match op {
        Opcode::ActivateAbility => {
            let mut ek = default_abilityOp();
            Some(Box::new(ek))
        }
        Opcode::ChangeState => {
            let state_change = decode_state(read_u8(cursor));
            let target = decode_player(read_u8(cursor));
            let mut ek = default_changeState();
            if let EffectKind::ChangeState { state_change: ref mut _bc_state_change, target: ref mut _bc_target, .. } = &mut ek {
                *_bc_state_change = Some(state_change.into());
                *_bc_target = Some(target.into());
            }
            Some(Box::new(ek))
        }
        Opcode::ChooseTargetPlayer => {
            let target = decode_player(read_u8(cursor));
            let mut ek = default_selectTarget();
            if let EffectKind::SelectTarget { target: ref mut _bc_target, .. } = &mut ek {
                *_bc_target = Some(target.into());
            }
            Some(Box::new(ek))
        }
        Opcode::DrawCard => {
            let target_count = read_u8(cursor);
            let source = decode_zone(read_u8(cursor));
            let mut ek = default_drawCards();
            if let EffectKind::DrawCards { target_count: ref mut _bc_target_count, source: ref mut _bc_source, .. } = &mut ek {
                *_bc_target_count = Some(target_count as u32);
                *_bc_source = Some(source.into());
            }
            Some(Box::new(ek))
        }
        Opcode::DrawUntilCount => {
            let target_count = read_u8(cursor);
            let source = decode_zone(read_u8(cursor));
            let mut ek = default_drawCards();
            if let EffectKind::DrawCards { target_count: ref mut _bc_target_count, source: ref mut _bc_source, .. } = &mut ek {
                *_bc_target_count = Some(target_count as u32);
                *_bc_source = Some(source.into());
            }
            Some(Box::new(ek))
        }
        Opcode::GainAbility => {
            let mut ek = default_abilityOp();
            Some(Box::new(ek))
        }
        Opcode::GainAbilityFromSource => {
            let mut ek = default_abilityOp();
            Some(Box::new(ek))
        }
        Opcode::GainResource => {
            let count = read_u8(cursor);
            let mut ek = default_gainResource();
            if let EffectKind::GainResource { value: ref mut _bc_value, .. } = &mut ek {
                *_bc_value = Some(count as u32);
            }
            Some(Box::new(ek))
        }
        Opcode::InvalidateAbility => {
            let mut ek = default_abilityOp();
            Some(Box::new(ek))
        }
        Opcode::ModifyCost => {
            let value = read_i8(cursor);
            let target = decode_player(read_u8(cursor));
            let mut ek = default_customOp();
            Some(Box::new(ek))
        }
        Opcode::ModifyRequiredHearts => {
            let value = read_i8(cursor);
            let mut ek = default_modifyHearts();
            if let EffectKind::ModifyHearts { value: ref mut _bc_value, .. } = &mut ek {
                *_bc_value = Some(value as u32);
            }
            Some(Box::new(ek))
        }
        Opcode::ModifyRequiredHeartsGlobal => {
            let value = read_i8(cursor);
            let mut ek = default_modifyHearts();
            if let EffectKind::ModifyHearts { value: ref mut _bc_value, .. } = &mut ek {
                *_bc_value = Some(value as u32);
            }
            Some(Box::new(ek))
        }
        Opcode::ModifyScore => {
            let value = read_i8(cursor);
            let per_unit = read_u8(cursor) != 0;
            let target = decode_player(read_u8(cursor));
            let mut ek = default_modifyScore();
            if let EffectKind::ModifyScore { value: ref mut _bc_value, per_unit: ref mut _bc_per_unit, target: ref mut _bc_target, .. } = &mut ek {
                *_bc_value = Some(value as u32);
                *_bc_per_unit = Some(per_unit);
                *_bc_target = Some(target.into());
            }
            Some(Box::new(ek))
        }
        Opcode::ModifyYellCount => {
            let value = read_i8(cursor);
            let mut ek = default_modifyScore();
            if let EffectKind::ModifyScore { value: ref mut _bc_value, .. } = &mut ek {
                *_bc_value = Some(value as u32);
            }
            Some(Box::new(ek))
        }
        Opcode::MoveCards => {
            let count = read_u8(cursor);
            let source = decode_zone(read_u8(cursor));
            let destination = decode_zone(read_u8(cursor));
            let mut ek = default_moveCards();
            if let EffectKind::MoveCards { count: ref mut _bc_count, source: ref mut _bc_source, destination: ref mut _bc_destination, .. } = &mut ek {
                *_bc_count = Some(count as u32);
                *_bc_source = Some(source.into());
                *_bc_destination = Some(destination.into());
            }
            Some(Box::new(ek))
        }
        Opcode::PlaceEnergyUnderMember => {
            let count = read_u8(cursor);
            let mut ek = default_moveCards();
            if let EffectKind::MoveCards { count: ref mut _bc_count, .. } = &mut ek {
                *_bc_count = Some(count as u32);
            }
            Some(Box::new(ek))
        }
        Opcode::PlayBatonTouch => {
            let mut ek = default_moveCards();
            Some(Box::new(ek))
        }
        Opcode::PositionChange => {
            let target = decode_player(read_u8(cursor));
            let mut ek = default_positionOp();
            if let EffectKind::PositionOp { target: ref mut _bc_target, .. } = &mut ek {
                *_bc_target = Some(target.into());
            }
            Some(Box::new(ek))
        }
        Opcode::Restriction => {
            let mut ek = default_restrictionOp();
            Some(Box::new(ek))
        }
        Opcode::SetBladeCount => {
            let value = read_u8(cursor);
            let mut ek = default_miscOp();
            if let EffectKind::MiscOp { value: ref mut _bc_value, .. } = &mut ek {
                *_bc_value = Some(value as u32);
            }
            Some(Box::new(ek))
        }
        Opcode::SetBladeType => {
            let mut ek = default_customOp();
            Some(Box::new(ek))
        }
        Opcode::SetCardIdentity => {
            let mut ek = default_changeState();
            Some(Box::new(ek))
        }
        Opcode::SetHeartType => {
            let value = decode_heart(read_u8(cursor));
            let mut ek = default_miscOp();
            if let EffectKind::MiscOp { heart_type: ref mut _bc_heart_type, .. } = &mut ek {
                *_bc_heart_type = Some(value.into());
            }
            Some(Box::new(ek))
        }
        Opcode::SuppressAbilityTrigger => {
            let mut ek = default_abilityOp();
            Some(Box::new(ek))
        }
        _ => None,
    }
}

fn decode_simple_effect(op: Opcode, cursor: &mut &[u8]) -> &'static str {
    match op {
        Opcode::ActivateAbility => {
            "activate_ability"
        }
        Opcode::ChangeState => {
            let state_change = decode_state(read_u8(cursor));
            let target = decode_player(read_u8(cursor));
            "change_state"
        }
        Opcode::ChooseTargetPlayer => {
            let target = decode_player(read_u8(cursor));
            "choose_target_player"
        }
        Opcode::DrawCard => {
            let target_count = read_u8(cursor);
            let source = decode_zone(read_u8(cursor));
            "draw_card"
        }
        Opcode::DrawUntilCount => {
            let target_count = read_u8(cursor);
            let source = decode_zone(read_u8(cursor));
            "draw_until_count"
        }
        Opcode::GainAbility => {
            "gain_ability"
        }
        Opcode::GainAbilityFromSource => {
            "gain_ability_from_source"
        }
        Opcode::GainResource => {
            let count = read_u8(cursor);
            "gain_resource"
        }
        Opcode::InvalidateAbility => {
            "invalidate_ability"
        }
        Opcode::ModifyCost => {
            let value = read_i8(cursor);
            let target = decode_player(read_u8(cursor));
            "modify_cost"
        }
        Opcode::ModifyRequiredHearts => {
            let value = read_i8(cursor);
            "modify_required_hearts"
        }
        Opcode::ModifyRequiredHeartsGlobal => {
            let value = read_i8(cursor);
            "modify_required_hearts_global"
        }
        Opcode::ModifyScore => {
            let value = read_i8(cursor);
            let per_unit = read_u8(cursor) != 0;
            let target = decode_player(read_u8(cursor));
            "modify_score"
        }
        Opcode::ModifyYellCount => {
            let value = read_i8(cursor);
            "modify_yell_count"
        }
        Opcode::MoveCards => {
            let count = read_u8(cursor);
            let source = decode_zone(read_u8(cursor));
            let destination = decode_zone(read_u8(cursor));
            "move_cards"
        }
        Opcode::PlaceEnergyUnderMember => {
            let count = read_u8(cursor);
            "place_energy_under_member"
        }
        Opcode::PlayBatonTouch => {
            "play_baton_touch"
        }
        Opcode::PositionChange => {
            let target = decode_player(read_u8(cursor));
            "position_change"
        }
        Opcode::Restriction => {
            "restriction"
        }
        Opcode::SetBladeCount => {
            let value = read_u8(cursor);
            "set_blade_count"
        }
        Opcode::SetBladeType => {
            "set_blade_type"
        }
        Opcode::SetCardIdentity => {
            "set_card_identity"
        }
        Opcode::SetHeartType => {
            let value = decode_heart(read_u8(cursor));
            "set_heart_type"
        }
        Opcode::SuppressAbilityTrigger => {
            "suppress_ability_trigger"
        }
        _ => "",
    }
}
